#!/bin/sh
# Xcode Cloud runs this automatically right after cloning the repo and before
# any build starts (see: https://developer.apple.com/documentation/xcode/writing-custom-build-scripts).
#
# The .xcodeproj is generated by XcodeGen and gitignored (project.yml is the
# source of truth — see README), so a bare clone has no project file for
# Xcode Cloud to build. Generate it here.
set -e

if ! command -v xcodegen >/dev/null 2>&1; then
  HOMEBREW_NO_AUTO_UPDATE=1 brew install xcodegen
fi

cd "${CI_PRIMARY_REPOSITORY_PATH:-..}"
xcodegen generate
